class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        m, n = len(matrix), len(matrix[0])
        clear_col0 = False
        # 1. record flags: matrix[i][0] marks row i, matrix[0][j] marks column j (j >= 1)
        for i in range(m):
            if matrix[i][0] == 0:
                clear_col0 = True
            for j in range(1, n):
                if matrix[i][j] == 0:
                    matrix[i][0] = 0
                    matrix[0][j] = 0
        # 2. clear the interior using the flags (bottom-up so row 0 stays intact until last)
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, 0, -1):
                if matrix[i][0] == 0 or matrix[0][j] == 0:
                    matrix[i][j] = 0
            if clear_col0:
                matrix[i][0] = 0

